package special

import (
	"math"

	"github.com/go-numerics/special/dd"
)

// gammaRelPiece is one piece of gammaRelPieces (zz_gammaRel_coeffs.go,
// generated by testdata/gen/fitgo gamma-rel): Γ(x) = G P(s) for x in
// [c - 1/16, c + 1/16), s = x - c, G = gh + gl = Γ(c), and
//
//	P(s) = 1 + s (a1 + s (a2 + s (a3 + s R(s)))),
//
// a1, a2, a3 double-doubles (a + al), R(s) = a4 + a5 s + ... + a13 s^9 in
// float64, stored r[0] = a13 ... r[9] = a4 (Horner order).
type gammaRelPiece struct {
	c, gh, gl float64
	a1, a1l   float64
	a2, a2l   float64
	a3, a3l   float64
	r         [10]float64
}

// gammaRel returns Γ(x) for 10 <= x < 172 (non-integer or not: it is the
// function) from the table: Γ(c) times the relative polynomial P, with the
// terms that reach more than 2^-62 of the result carried as double-doubles
// (the products by TwoProd, the sums by TwoSum) and the rest in float64
// (their largest, a4 s^4, is 0.006 of P, rounded at 2^-53 of itself by the
// Horner steps: 2^-61 at worst, 2^-64 typically). x - 10, 8(x - 10) and
// s = x - c are exact: every operand is a multiple of ulp(x) or of 1/16 and
// the results are smaller. The product G P is rounded once.
func gammaRel(x float64) float64 {
	p := &gammaRelPieces[int(float64((x-10)*8))]
	s := x - p.c
	r := p.r[0]
	r = math.FMA(r, s, p.r[1])
	r = math.FMA(r, s, p.r[2])
	r = math.FMA(r, s, p.r[3])
	r = math.FMA(r, s, p.r[4])
	r = math.FMA(r, s, p.r[5])
	r = math.FMA(r, s, p.r[6])
	r = math.FMA(r, s, p.r[7])
	r = math.FMA(r, s, p.r[8])
	r = math.FMA(r, s, p.r[9])
	// u3 = a3 + s R, u2 = a2 + s u3, u1 = a1 + s u2, w = 1 + s u1, in double-double
	u3h, e3 := dd.TwoSum(p.a3, float64(s*r))
	u3l := e3 + p.a3l
	q3h, q3e := dd.TwoProd(s, u3h)
	q3l := math.FMA(s, u3l, q3e)
	u2h, e2 := dd.TwoSum(p.a2, q3h)
	u2l := e2 + (p.a2l + q3l)
	q2h, q2e := dd.TwoProd(s, u2h)
	q2l := math.FMA(s, u2l, q2e)
	u1h, e1 := dd.TwoSum(p.a1, q2h)
	u1l := e1 + (p.a1l + q2l)
	q1h, q1e := dd.TwoProd(s, u1h)
	q1l := math.FMA(s, u1l, q1e)
	wh, we := dd.FastTwoSum(1, q1h) // |s u1| < 0.34
	wl := we + q1l
	h, e := dd.TwoProd(p.gh, wh)
	return h + (e + math.FMA(p.gh, wl, float64(p.gl*wh)))
}
